use std::fmt::*;
struct Header(&'static str);
impl Display for Header {
    fn fmt(&self, f: &mut Formatter) -> Result { write!(f, "{}", self.0) }
}
#[derive(Debug)] struct Data(i32);
struct Unformatted(i32);

fn summarize<T, U>(h: T, d: U) -> String ⟦slot1⟧ {
    format!("{h}: {:?}", d)
}

fn main() {
    let s = summarize(Header("Info"), ⟦slot2⟧);
    assert_eq!(s, "Info: Data(42)");
}

tests:
#[test]
fn test_summarize() {
    let s = summarize(Header("Test"), Data(99));
    assert_eq!(s, "Test: Data(99)");
}
